import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """Minimize an operation-level disjunctive MILP, then validate and polish
    its transaction-rank order with the simulator's exact objective."""
    n = workload.num_txns
    if n <= 1:
        seq = list(range(n))
        return workload.get_opt_seq_cost(seq), seq

    cache = {}

    def cost(seq):
        """Return and memoize the simulator cost of one transaction order."""
        key = tuple(seq)
        if key not in cache:
            cache[key] = workload.get_opt_seq_cost(seq)
        return cache[key]

    def descend(seq, value):
        """Perform exact insertion descent under the actual simulator metric."""
        for _ in range(4):
            improved = False
            for source in range(n):
                txn = seq[source]
                base = seq[:source] + seq[source + 1:]
                move_cost, move_seq = value, seq
                for dest in range(n):
                    candidate = base[:dest] + [txn] + base[dest:]
                    candidate_cost = cost(candidate)
                    if candidate_cost < move_cost:
                        move_cost, move_seq = candidate_cost, candidate
                if move_cost < value:
                    value, seq, improved = move_cost, move_seq, True
            if not improved:
                break
        return value, seq

    # Preserve a simulator-scored beam as a reliable incumbent/fallback.  In
    # particular, this protects against workloads whose internal representation
    # cannot be parsed below or whose lock semantics are stricter than the
    # operation-level model.
    width = max(2, min(8, int(num_seqs), n))
    beam = [(cost([i]), [i]) for i in range(n)]
    beam.sort(key=lambda x: (x[0], x[1]))
    beam = beam[:width]
    for _ in range(1, n):
        expanded = []
        for _, prefix in beam:
            used = set(prefix)
            for txn in range(n):
                if txn not in used:
                    candidate = prefix + [txn]
                    expanded.append((cost(candidate), candidate))
        expanded.sort(key=lambda x: (x[0], x[1]))
        beam = expanded[:width]

    best_cost, best_seq = float("inf"), None
    for value, seq in beam[:min(4, len(beam))]:
        value, seq = descend(seq, value)
        if value < best_cost:
            best_cost, best_seq = value, seq

    # Extract textual transaction programs without depending on a particular
    # Workload implementation name.  Standard workloads expose one of these as
    # a dict/list with exactly num_txns entries.
    programs = None
    for name in ("transactions", "txns", "workload", "data"):
        value = getattr(workload, name, None)
        if isinstance(value, dict) and len(value) == n:
            programs = list(value.values())
            break
        if isinstance(value, (list, tuple)) and len(value) == n:
            programs = list(value)
            break
    if programs is None:
        for value in vars(workload).values():
            if isinstance(value, dict) and len(value) == n:
                if all(isinstance(x, str) for x in value.values()):
                    programs = list(value.values())
                    break
            elif isinstance(value, (list, tuple)) and len(value) == n:
                if all(isinstance(x, str) for x in value):
                    programs = list(value)
                    break

    ops = []
    if programs is not None:
        try:
            for txn, program in enumerate(programs):
                for token in str(program).split():
                    kind, key = token.split("-", 1)
                    if kind in ("r", "w"):
                        ops.append((txn, kind == "w", key))
        except ValueError:
            ops = []

    # The MILP has a start variable per operation, rank variables per
    # transaction, and one binary global order variable for every transaction
    # pair.  Coupling every conflicting operation pair to that binary guarantees
    # that the result is representable by the returned transaction permutation.
    q = len(ops)
    if q and q <= 400:
        try:
            from collections import defaultdict
            from scipy.optimize import Bounds, LinearConstraint, milp
            from scipy.sparse import coo_matrix

            by_key = defaultdict(list)
            for op_id, (txn, is_write, key) in enumerate(ops):
                by_key[key].append((op_id, txn, is_write))

            conflicts = []
            for entries in by_key.values():
                for a in range(len(entries)):
                    oa, ta, wa = entries[a]
                    for b in range(a + 1, len(entries)):
                        ob, tb, wb = entries[b]
                        if ta != tb and (wa or wb):
                            conflicts.append((oa, ob, ta, tb))

            pair_index = {}
            for i in range(n):
                for j in range(i + 1, n):
                    pair_index[i, j] = len(pair_index)

            rank0 = q
            order0 = q + n
            cmax = order0 + len(pair_index)
            variables = cmax + 1
            upper_rows, upper_bounds = [], []

            def add(row, bound):
                upper_rows.append(row)
                upper_bounds.append(bound)

            # Consecutive operations in each transaction have unit duration.
            previous = {}
            for op_id, (txn, _, _) in enumerate(ops):
                if txn in previous:
                    add({previous[txn]: 1, op_id: -1}, -1)
                previous[txn] = op_id
                add({op_id: 1, cmax: -1}, -1)

            m = q
            # Rank/order constraints remove cyclic pair orientations.
            for (i, j), p in pair_index.items():
                x = order0 + p
                add({rank0 + i: 1, rank0 + j: -1, x: n}, n - 1)
                add({rank0 + j: 1, rank0 + i: -1, x: -n}, -1)

            # If x_ij is one, i precedes j; otherwise j precedes i.  These two
            # big-M rows impose that direction on every RW/WW operation pair.
            for oa, ob, ta, tb in conflicts:
                i, j = (ta, tb) if ta < tb else (tb, ta)
                x = order0 + pair_index[i, j]
                if ta == i:
                    add({oa: 1, ob: -1, x: m}, m - 1)
                    add({ob: 1, oa: -1, x: -m}, -1)
                else:
                    add({ob: 1, oa: -1, x: m}, m - 1)
                    add({oa: 1, ob: -1, x: -m}, -1)

            rows, cols, data = [], [], []
            for r, row in enumerate(upper_rows):
                for col, value in row.items():
                    rows.append(r)
                    cols.append(col)
                    data.append(value)
            matrix = coo_matrix((data, (rows, cols)),
                                shape=(len(upper_rows), variables)).tocsr()

            objective = [0.0] * variables
            objective[cmax] = 1.0
            lower = [0.0] * variables
            upper = [float(m)] * q + [float(n - 1)] * n + [1.0] * len(pair_index) + [float(m)]
            integrality = [0] * q + [1] * n + [1] * len(pair_index) + [0]

            result = milp(
                c=objective, integrality=integrality,
                bounds=Bounds(lower, upper),
                constraints=LinearConstraint(matrix, [-float("inf")] * len(upper_rows),
                                             upper_bounds),
                options={"time_limit": 25.0, "mip_rel_gap": 0.0},
            )
            if result.x is not None:
                milp_seq = sorted(range(n), key=lambda t: (result.x[rank0 + t], t))
                milp_cost, milp_seq = descend(milp_seq, cost(milp_seq))
                if milp_cost < best_cost:
                    best_cost, best_seq = milp_cost, milp_seq
        except Exception:
            # scipy is optional in some execution environments; the exact
            # simulator-scored incumbent above remains valid in that case.
            pass

    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")
